// ── Helper: benchmark a function in a loop, print ns/op ──────────────
template<typename Fn>
static void BenchmarkFormat(const char* label, int iterations, Fn&& fn) {
    // Warmup call
    fn();

    auto alloc_before = chaos_gc_get_allocated_bytes_for_current_thread();
    auto start = Clock::now();
    for (int i = 0; i < iterations; i++) {
        fn();
    }
    auto end = Clock::now();
    auto alloc_after = chaos_gc_get_allocated_bytes_for_current_thread();

    double total_ns = std::chrono::duration<double, std::nano>(end - start).count();
    double ns_per_op = total_ns / iterations;
    int64_t alloc_per_op = (alloc_after - alloc_before) / iterations;
    printf("  %s: %.1f ns/op, %lld B/op (%d iterations)\n",
           label, ns_per_op, (long long)alloc_per_op, iterations);
    std::fflush(stdout);
}

